import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { Box, TextField, Button, Typography, Grid, Paper } from '@mui/material';
import * as d3 from 'd3';
import axios from 'axios';
import cleanedData from './cleaned_real_estate_data.csv';

function Predict() {
    const [formData, setFormData] = useState({
        location: '',
        size: '',
        total_sqft: '',
        bathrooms: '',
    });
    const [predictions, setPredictions] = useState(null);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState(null);
    const [csvData, setCsvData] = useState([]);

    const validAreas = useMemo(() => [
        'Electronic City',
        'Whitefield',
        'Indira Nagar',
        'Koramangala',
        'BTM Layout',       // Additional data point
        'Jayanagar',       // Additional data point
        'Malleshwaram',    // Additional data point
        'Brigade Road',     // Additional data point
    ], []);

    const drawD3Chart = useCallback(() => {
        d3.select("#d3-bar-chart").selectAll("*").remove();

        const margin = { top: 20, right: 30, bottom: 40, left: 40 },
              width = 600 - margin.left - margin.right, // Increased width
              height = 400 - margin.top - margin.bottom;

        const svg = d3.select("#d3-bar-chart")
            .append("svg")
            .attr("width", width + margin.left + margin.right)
            .attr("height", height + margin.top + margin.bottom)
            .append("g")
            .attr("transform", `translate(${margin.left}, ${margin.top})`);

        // Extract average price for the selected location
        const locationData = csvData.filter(item => item.location === formData.location);
        const averagePrice = locationData.length > 0 ? d3.mean(locationData, d => parseFloat(d.price)) : 0;

        const data = [
            { area: 'Predicted Price', price: predictions, color: '#FF5733' }, // Highlighted color for predicted value
            { area: 'Average Price', price: averagePrice, color: '#3b82f6' }, // Regular color for average price
            ...validAreas.map(area => {
                const entry = csvData.find(item => item.location === area);
                return { area: area, price: entry ? parseFloat(entry.price) : 0, color: '#3b82f6' };
            }),
        ];

        const x = d3.scaleBand()
            .domain(data.map(d => d.area))
            .range([0, width])
            .padding(0.1);

        const y = d3.scaleLinear()
            .domain([0, d3.max(data, d => d.price)])
            .nice()
            .range([height, 0]);

        svg.append("g")
            .selectAll(".bar")
            .data(data)
            .enter()
            .append("rect")
            .attr("class", "bar")
            .attr("x", d => x(d.area))
            .attr("width", x.bandwidth())
            .attr("y", d => y(d.price))
            .attr("height", d => height - y(d.price))
            .attr("fill", d => d.color); // Use color from the data

        svg.append("g")
            .attr("transform", `translate(0, ${height})`)
            .call(d3.axisBottom(x).tickSize(0).tickPadding(10));

        svg.append("g")
            .call(d3.axisLeft(y));

        // Add labels to the bars
        svg.selectAll(".label")
            .data(data)
            .enter()
            .append("text")
            .attr("class", "label")
            .attr("x", d => x(d.area) + x.bandwidth() / 2)
            .attr("y", d => y(d.price) - 5) // position above the bar
            .attr("text-anchor", "middle")
            .text(d => d.price.toFixed(2)) // format the price
            .style("fill", "#000") // color of the text
            .style("font-size", "12px") // font size
            .style("font-family", "Arial, sans-serif"); // font family

    }, [predictions, csvData, validAreas, formData.location]);

    const handleChange = (e) => {
        setFormData({
            ...formData,
            [e.target.name]: e.target.value
        });
    };

    const handlePredict = async () => {
        setLoading(true);
        setError(null);

        try {
            const response = await axios.post('http://localhost:8000/predict', {
                location: formData.location,
                size: parseFloat(formData.size),
                total_sqft: parseFloat(formData.total_sqft),
                bathrooms: parseInt(formData.bathrooms, 10),
            });

            setPredictions(response.data.prediction);
        } catch (err) {
            setError(err.response ? err.response.data.detail : err.message);
        } finally {
            setLoading(false);
        }
    };

    const isFormComplete = formData.location && formData.size && formData.total_sqft && formData.bathrooms;

    useEffect(() => {
        d3.csv(cleanedData).then(data => {
            setCsvData(data);
        });
    }, []);

    useEffect(() => {
        if (predictions && csvData.length > 0) {
            drawD3Chart();
        }
    }, [predictions, csvData, drawD3Chart]);

    return (
        <Box sx={{ padding: '50px', maxWidth: '1500px', margin: '0 auto', marginTop: '40px' }}>
            <Typography variant="h4" gutterBottom align="center">
                Predict With Us
            </Typography>

            <Grid container spacing={6} justifyContent="center" alignItems="flex-start">
                <Grid item xs={12} md={5}>
                    <Box component="form" sx={{ display: 'flex', flexDirection: 'column', gap: 3 }}>
                        <TextField
                            select
                            label="Location"
                            name="location"
                            value={formData.location}
                            onChange={handleChange}
                            required    
                            SelectProps={{
                                native: true,
                            }}
                        >
                            <option value=""></option>
                            {validAreas.map((area, index) => (
                                <option key={index} value={area}>{area}</option>
                            ))}
                        </TextField>

                        <TextField label="Bedroom-Hall-Kitchen (BHK)"
                            name="size"
                            value={formData.size}
                            onChange={handleChange}
                            type="number"
                            required
                        />

                        <TextField label="Total Square Feet"
                            name="total_sqft"
                            value={formData.total_sqft}
                            onChange={handleChange}
                            type="number"
                            required
                        />

                        <TextField label="Bathrooms"
                            name="bathrooms"
                            value={formData.bathrooms}
                            onChange={handleChange}
                            type="number"
                            required
                        />

                        <Button
                            variant="contained"
                            onClick={handlePredict}
                            disabled={!isFormComplete || loading} // Disable if form is incomplete or loading
                        >
                            {loading ? 'Loading...' : 'Get Predictions'}
                        </Button>
                        {error && <Typography color="error">{error}</Typography>}
                    </Box>
                </Grid>

                {predictions && (
                    <Grid item xs={12} md={5}>
                        <Paper elevation={3} sx={{ padding: '20px', textAlign: 'center' }}>
                            <Typography variant="h6">
                                Predicted Price: ${predictions.toFixed(2)}
                            </Typography>
                        </Paper>
                    </Grid>
                )}
            </Grid>

            {predictions && (
                <Box sx={{ marginTop: '50px', textAlign: 'center' }}>
                    <Typography variant="h6">
                        Prediction Visualization
                    </Typography>
                    <div id="d3-bar-chart" style={{ height: '400px' }} />
                </Box>
            )}
        </Box>
    );
}

export default Predict;
